<div class="card">
  <%= form_with model: [ :moderate, quiz ] do |f| %>
    <% if quiz.errors.any? %>
      <div class="errors" role="alert">
        <% if quiz.errors.full_messages.size == 1 %>
          <%= quiz.errors.full_messages.first %>
        <% else %>
          <ul>
            <% quiz.errors.full_messages.each do |message| %>
              <li><%= message %></li>
            <% end %>
          </ul>
        <% end %>
      </div>
    <% end %>

    <div class="field">
      <%= f.label :title, "Title" %>
      <%= f.text_field :title, class: "input", autofocus: true, "aria-required": "true" %>
    </div>

    <div class="buttons">
      <%= f.submit "Save quiz", class: "btn btn--pink" %>
      <%= link_to "Cancel", quiz.persisted? ? moderate_quiz_path(quiz) : moderate_root_path, class: "btn btn--ghost" %>
    </div>
  <% end %>
</div>
