cat <<'EOF' >> app/assets/stylesheets/quizzy.css

.leader__name { display: flex; align-items: center; gap: 0.4em; min-width: 0; overflow: visible; }
.leader__name-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
